<script setup>
import {computed,ref,watch} from 'vue'
import {geneticSteps,orderCrossover} from '../services/local-search.mjs'
import SimulationControls from './SimulationControls.vue'
import SearchTraceCode from './SearchTraceCode.vue'
const seed=ref(7),mutation=ref(.08),elitism=ref(true),step=ref(0),left=ref(2),right=ref(6)
const trace=computed(()=>Array.from(geneticSteps({seed:seed.value,mutation:mutation.value,elitism:elitism.value}))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),key=computed(()=>JSON.stringify([seed.value,mutation.value,elitism.value]))
watch(key,()=>step.value=0)
const parent1=[3,5,7,2,1,6,4,8],parent2=[2,5,7,6,8,1,3,4],child=computed(()=>orderCrossover(parent1,parent2,left.value,right.value))
watch(left,()=>{if(right.value<=left.value)right.value=left.value+1})
const message=computed(()=>{const s=state.value;if(s.phase==='evaluate')return 'Fitness là số cặp không tấn công nhau. Chuẩn hóa bốn điểm fitness thành xác suất chọn cha mẹ.';if(s.phase==='crossover')return `Chọn cá thể ${s.parents[0]+1} và ${s.parents[1]+1}. Giữ ${s.cut} gene đầu từ cha thứ nhất, nối phần sau từ cha thứ hai.`;if(s.phase==='mutation')return `Đột biến thay hàng bằng một hàng khác ở ${s.changes.length} cột. Các cột được thay có viền đỏ.`;if(s.phase==='replace')return 'Thay quần thể. Khi giữ tinh hoa, một cá thể tốt nhất của thế hệ trước được giữ nguyên.';if(s.phase==='budget')return 'Dừng sau 8 thế hệ. Kỷ lục đã quan sát được lưu riêng, không chứng minh tối ưu toàn cục.';return 'Mỗi cá thể là tám số hàng theo cột. Fitness = 28 trừ số cặp xung đột.'})
</script>
<template><section class="math-lab genetic-search" aria-label="Mô phỏng giải thuật di truyền"><div class="genetic-settings"><label>Hạt giống<select v-model.number="seed"><option v-for="i in [1,7,23,42]" :key="i">{{ i }}</option></select></label><label>Xác suất đột biến mỗi gene<select v-model.number="mutation"><option v-for="i in [0,.01,.08,.3,1]" :key="i">{{ i }}</option></select></label><label class="elite-control"><input v-model="elitism" type="checkbox">Giữ một cá thể tinh hoa</label></div><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><div class="population"><article v-for="(q,i) in state.population" :key="i"><p>Cá thể {{ i+1 }} · Fitness {{ state.fitness[i] }}</p><div class="genes"><span v-for="(v,j) in q" :key="j">{{ v+1 }}</span></div><p v-if="state.probabilities">P(chọn) = {{ (100*state.probabilities[i]).toFixed(2) }}%</p></article></div><div v-if="state.child" class="child-view"><p>Con đang tạo <span v-if="state.cut">· Điểm cắt {{ state.cut }}</span></p><div class="genes"><span v-for="(v,j) in state.child" :key="j" :class="{changed:state.changes?.includes(j),retained:state.cut&&j<state.cut}">{{ v+1 }}</span></div><p v-if="state.before">Trước đột biến: {{ state.before.map(x=>x+1).join(' ') }}.</p></div><p class="genetic-status" role="status">{{ message }}</p><p>Kỷ lục fitness {{ state.bestFitness }}/28. Cá thể tốt nhất: {{ state.best.map(x=>x+1).join(' ') }}.</p><SearchTraceCode name="geneticSteps" :phase="state.phase"/><details class="ox-panel"><summary>Thử lai OX dành cho hoán vị TSP</summary><p>Lai một điểm ở trên phù hợp cách mã hóa hàng của hậu. Với chu trình TSP, phép OX dưới đây giữ mỗi thành phố đúng một lần.</p><label>Đầu đoạn giữ<select v-model.number="left"><option v-for="i in 7" :key="i" :value="i-1">Vị trí {{ i }}</option></select></label><label>Cuối đoạn giữ<select v-model.number="right"><option v-for="i in 8-left" :key="i" :value="left+i">Vị trí {{ left+i }}</option></select></label><div v-for="(q,i) in [parent1,parent2,child]" :key="i"><p>{{ ['Cha thứ nhất','Cha thứ hai','Con OX'][i] }}</p><div class="genes"><span v-for="(v,j) in q" :key="j" :class="{retained:i!==1&&j>=left&&j<right}">{{ v }}</span></div></div><p>Giữ đoạn của cha thứ nhất. Đọc cha thứ hai từ sau điểm cắt, vòng về đầu, bỏ gene đã giữ rồi điền các chỗ trống theo cùng vòng.</p></details></section></template>
<style scoped>
.genetic-search{min-width:0}.genetic-settings{display:flex;flex-wrap:wrap;gap:12px}.genetic-search label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.genetic-search select{min-height:44px;max-width:100%;min-width:0;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:inherit}.genetic-search .elite-control{display:flex;align-items:center;min-height:44px;gap:8px}.elite-control input{width:22px;height:22px;accent-color:var(--tim)}.population{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.population article,.child-view{padding:12px;border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper);min-width:0}.population p,.child-view p{margin:4px 0 10px;font:var(--fs-small)/1.7 var(--font-ui)}.genes{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:3px}.genes span{display:grid;place-items:center;padding:8px 0;border:1px solid var(--rule);border-radius:var(--radius);font:16px var(--font-code)}.genes span.changed{border:2px solid var(--do)}.genes span.retained{background:var(--tim-soft);border-color:var(--tim)}.child-view{margin-top:12px}.genetic-status{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}summary{min-height:44px;cursor:pointer}.ox-panel label{margin:12px 0}select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:600px){.population{grid-template-columns:1fr}.genetic-settings{display:grid;grid-template-columns:1fr}}
</style>
